from __future__ import annotations

def weights(epsilon: float) -> tuple[float, float]:
    if epsilon < 0:
        raise ValueError("epsilon must be nonnegative")
    denominator = 1.0 + epsilon * epsilon
    return 1.0 / denominator, epsilon * epsilon / denominator

for e in (1.0, .1, .01, .001, .0001):
    w0, w1 = weights(e)
    print(f"epsilon={e:g}: ({w0:.12g}, {w1:.12g}), sum={w0+w1:.12g}")

from __future__ import annotations
from fractions import Fraction

def event_mass(n: int, visible_count: int, reservoir: bool) -> tuple[Fraction, Fraction]:
    if not 0 <= visible_count <= n:
        raise ValueError("visible_count must lie between 0 and n")
    flag = int(reservoir)
    return Fraction(flag), Fraction(visible_count - n * flag)

def standard_part(value: tuple[Fraction, Fraction]) -> Fraction:
    return value[0]

for k, r in ((1, False), (4, False), (0, True), (4, True)):
    mass = event_mass(4, k, r)
    print(k, r, mass, standard_part(mass))

from __future__ import annotations
from typing import Sequence

def select(reservoir: float, visible: Sequence[float], penalty: float) -> tuple[float, str, float]:
    if penalty >= 0:
        raise ValueError("penalty must be negative")
    best = max((x + penalty for x in visible), default=float("-inf"))
    margin = reservoir - best
    return (reservoir, "reservoir", margin) if margin >= 0 else (best, "visible", margin)

print(select(3.0, [2.0, 4.0, 1.0], -2.0))
print(select(3.0, [2.0, 6.5, 1.0], -2.0))

